import React, { useState, useEffect } from 'react';
import InternshipCard from './InternshipCard'; // تأكد أن هذا المسار صحيح
import './OpportunitiesPage.css'; // تأكد أن هذا المسار صحيح

const OpportunitiesPage = () => {
  // بيانات الفرص التجريبية
  const allOpportunities = [
    {
      id: '1',
      title: 'Front-end Developer Internship',
      company: 'Tech Solutions Inc.',
      location: 'Remote',
      duration: '3 Months',
      description: 'Join our team to build amazing user interfaces using React and modern web technologies. You will work on various client-side projects and learn best practices.',
      skills: ['React', 'JavaScript', 'HTML', 'CSS', 'Git'],
      stipend: 'Paid',
      postedDate: '2024-01-15',
    },
    {
      id: '2',
      title: 'Data Analyst Intern',
      company: 'Data Insights Co.',
      location: 'New York, NY',
      duration: '6 Months',
      description: 'Assist in analyzing large datasets, creating reports, and deriving actionable insights. You will use Python and SQL to extract and transform data.',
      skills: ['Python', 'SQL', 'Excel', 'Data Visualization', 'Statistics'],
      stipend: 'Paid',
      postedDate: '2024-01-20',
    },
    {
      id: '3',
      title: 'Marketing Intern',
      company: 'Global Marketing Agency',
      location: 'London, UK',
      duration: '4 Months',
      description: 'Support marketing campaigns, social media management, and content creation. Gain experience in digital marketing strategies and analytics.',
      skills: ['Social Media', 'Content Creation', 'SEO Basics', 'Communication'],
      stipend: 'Unpaid',
      postedDate: '2024-01-25',
    },
    {
      id: '4',
      title: 'Back-end Developer Internship',
      company: 'Cloud Innovators',
      location: 'Remote',
      duration: '5 Months',
      description: 'Develop and maintain server-side logic, databases, and APIs. Experience with Node.js and MongoDB is a plus. Contribute to scalable cloud solutions.',
      skills: ['Node.js', 'Express', 'MongoDB', 'RESTful APIs', 'AWS Basics'],
      stipend: 'Paid',
      postedDate: '2024-02-01',
    },
    {
      id: '5',
      title: 'UI/UX Design Intern',
      company: 'Creative Studio',
      location: 'San Francisco, CA',
      duration: '3 Months',
      description: 'Work on user research, wireframing, prototyping, and user interface design. Help create intuitive and aesthetically pleasing digital products.',
      skills: ['Figma', 'Sketch', 'Adobe XD', 'User Research', 'Prototyping'],
      stipend: 'Paid',
      postedDate: '2024-02-05',
    },
    {
      id: '6',
      title: 'Software Quality Assurance Intern',
      company: 'Quality First Tech',
      location: 'Austin, TX',
      duration: '4 Months',
      description: 'Participate in testing web and mobile applications, identify bugs, and ensure product quality. Learn about automated testing frameworks.',
      skills: ['Manual Testing', 'Jira', 'Test Cases', 'Attention to Detail'],
      stipend: 'Paid',
      postedDate: '2024-02-10',
    },
  ];

  // حالات لتخزين الفرص المعروضة، مصطلح البحث، وفلاتر مختلفة
  const [allopportunities, setOpportunities] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLocation, setFilterLocation] = useState('');
  const [filterDuration, setFilterDuration] = useState('');
  const [filterStipend, setFilterStipend] = useState('');

  // استخراج القيم الفريدة للفلاتر من allOpportunities
  const uniqueLocations = [...new Set(allOpportunities.map(opp => opp.location))];
  const uniqueDurations = [...new Set(allOpportunities.map(opp => opp.duration))];
  const uniqueStipends = [...new Set(allOpportunities.map(opp => opp.stipend))];
  // useEffect لجلب الفرص عند تحميل المكون لأول مرة
  // تم تصحيح الخطأ الأول هنا بإضافة allOpportunities إلى مصفوفة التبعيات
  useEffect(() => {
    setOpportunities(allOpportunities);
  }, [allOpportunities]); // <--- تم إضافة allOpportunities هنا

  // useEffect لتطبيق الفلاتر والبحث كلما تغير أي من حالات البحث أو الفلترة
  // تم تصحيح الخطأ الثاني هنا بإضافة allOpportunities إلى مصفوفة التبعيات
  useEffect(() => {
    let filtered = allOpportunities; // allOpportunities تستخدم هنا

    // تطبيق البحث
    if (searchTerm) {
      const lowerCaseSearchTerm = searchTerm.toLowerCase();
      filtered = filtered.filter(opp =>
        opp.title.toLowerCase().includes(lowerCaseSearchTerm) ||
        opp.description.toLowerCase().includes(lowerCaseSearchTerm) ||
        opp.skills.some(skill => skill.toLowerCase().includes(lowerCaseSearchTerm))
      );
    



    // تطبيق فلتر الموقع
    if (filterLocation) {
      filtered = filtered.filter(opp => opp.location === filterLocation);
    }

    // تطبيق فلتر المدة
    if (filterDuration) {
      filtered = filtered.filter(opp => opp.duration === filterDuration);
    }

    // تطبيق فلتر المكافأة (Stipend)
    if (filterStipend) {
      filtered = filtered.filter(opp => opp.stipend === filterStipend);
    }

    setOpportunities(filtered);
  }}, [searchTerm, filterLocation, filterDuration, filterStipend, allOpportunities]); // <--- تم إضافة allOpportunities هنا

  return (
    <div className="opportunities-page">
      <h1>Discover Internship Opportunities</h1>

      <div className="filters-container">
        {/ حقل البحث /}
        <input
          type="text"
          placeholder="Search by title, company, or skills..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />

        {/ فلتر الموقع /}
        <select
          value={filterLocation}
          onChange={(e) => setFilterLocation(e.target.value)}
          className="filter-select"
        >
          <option value="">All Locations</option>
          {uniqueLocations.map(loc => (
            <option key={loc} value={loc}>{loc}</option>
          ))}
        </select>

        {/ فلتر المدة /}
        <select
          value={filterDuration}
          onChange={(e) => setFilterDuration(e.target.value)}
          className="filter-select"
        >
          <option value="">All Durations</option>
          {uniqueDurations.map(dur => (
            <option key={dur} value={dur}>{dur}</option>
          ))}
        </select>

        {/ فلتر المكافأة (Stipend) /}
        <select
          value={filterStipend}
          onChange={(e) => setFilterStipend(e.target.value)}
          className="filter-select"
        >
          <option value="">All Stipends</option>
          {uniqueStipends.map(stip => (
            <option key={stip} value={stip}>{stip}</option>
          ))}
        </select>
      </div>

      <div className="opportunities-list">
        {allopportunities.length > 0 ? (
          allopportunities.map(opportunity => (
            <InternshipCard key={opportunity.id} opportunity={opportunity} />
          ))
        ) : (
          <p className="no-opportunities">No opportunities found matching your criteria.</p>
        )}
      </div>
    </div>
  );
};

export default OpportunitiesPage;
